// Some portions generated by Co-Pilot
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.File;
import java.util.Set;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class LmdbStorePartialIndexesTest {

	@TempDir
	File dir;

	@ParameterizedTest
	@ValueSource(strings = { "cs,scpo", "cs,sp,psoc", "cs,sp,op,posc" })
	void contextSubjectIndexSupportsGraphQueriesAndRemoval(String indexes) {
		var vf = SimpleValueFactory.getInstance();
		IRI s = vf.createIRI("urn:test:s");
		IRI p = vf.createIRI("urn:test:p");
		IRI o = vf.createIRI("urn:test:o");
		IRI graph = vf.createIRI("urn:test:graph");
		SailRepository repo = open(indexes);
		try {
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.begin();
				connection.add(s, p, o);
				connection.add(s, p, o, graph);
				connection.add(o, p, s, graph);
				connection.commit();
				assertEquals(1, connection.size((Resource) null));
				assertEquals(2, connection.size(graph));
				assertEquals(1, Iterations.asList(connection.getStatements(null, null, null, false,
						(Resource) null)).size());
				try (var result = connection.prepareTupleQuery(
						"SELECT ?s ?p ?o WHERE { GRAPH <urn:test:graph> { ?s ?p ?o } }").evaluate()) {
					assertEquals(2, Iterations.asList(result).size());
				}
				connection.remove((Resource) null, null, null, graph);
				assertEquals(0, connection.size(graph));
				assertEquals(1, connection.size((Resource) null));
			}
		} finally {
			repo.shutDown();
		}
	}

	@Test
	void enablingPartialIndexesBackfillsExistingRepository() {
		IRI s = SimpleValueFactory.getInstance().createIRI("urn:test:s");
		IRI p = SimpleValueFactory.getInstance().createIRI("urn:test:p");
		IRI o = SimpleValueFactory.getInstance().createIRI("urn:test:o");
		SailRepository repo = open("psoc,posc");
		try {
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.add(s, p, o);
			}
		} finally {
			repo.shutDown();
		}
		for (String indexes : new String[] { "sp,op,psoc,posc", null, "psoc,posc" }) {
			repo = open(indexes);
			try {
				try (RepositoryConnection connection = repo.getConnection()) {
					assertEquals(1, Iterations.asList(connection.getStatements(s, null, null, false)).size());
					assertEquals(1, Iterations.asList(connection.getStatements(null, null, o, false)).size());
					assertEquals(1, connection.size());
				}
			} finally {
				repo.shutDown();
			}
		}
	}

	@Test
	void termIndexChangesPersistWithoutChangingStatementIndexes() {
		LmdbStoreConfig config = new LmdbStoreConfig("psoc,posc,sp,op");
		for (String termIndex : new String[] { "posc", "ospc", "ospc" }) {
			config.setTripleTermIndexes(termIndex);
			SailRepository repo = new SailRepository(new LmdbStore(dir, config));
			try {
				repo.init();
			} finally {
				repo.shutDown();
			}
			StoreProperties properties = new StoreProperties(dir);
			properties.load();
			assertEquals(Set.of("spoc", "cspo", termIndex),
					TripleIndex.parseIndexSpecList(properties.getTripleTermIndexes()));
			assertEquals(Set.of("psoc", "posc", "sp", "op"),
					TripleIndex.parseStatementIndexSpecList(properties.getTripleIndexes()));
		}
	}

	@Test
	void partialIndexesReturnCompleteSparqlResultsAndSupportRemoval() {
		IRI s = SimpleValueFactory.getInstance().createIRI("urn:test:s");
		IRI p = SimpleValueFactory.getInstance().createIRI("urn:test:p");
		IRI o = SimpleValueFactory.getInstance().createIRI("urn:test:o");
		IRI other = SimpleValueFactory.getInstance().createIRI("urn:test:other");
		SailRepository repo = open("psoc,posc,sp,op");
		try {
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.begin();
				connection.add(s, p, o);
				connection.add(s, p, other);
				connection.add(other, p, o);
				connection.commit();
				try (var result = connection.prepareTupleQuery("SELECT ?p ?o WHERE { <urn:test:s> ?p ?o }")
						.evaluate()) {
					assertEquals(2, Iterations.asList(result).size());
				}
				try (var result = connection.prepareTupleQuery("SELECT ?s ?p WHERE { ?s ?p <urn:test:o> }")
						.evaluate()) {
					assertEquals(2, Iterations.asList(result).size());
				}
				connection.remove(s, p, o);
				assertEquals(1, Iterations.asList(connection.getStatements(s, null, null, false)).size());
				assertEquals(1, Iterations.asList(connection.getStatements(null, null, o, false)).size());
				connection.remove(s, null, null);
				assertEquals(0, Iterations.asList(connection.getStatements(s, null, null, false)).size());
			}
		} finally {
			repo.shutDown();
		}
	}

	private SailRepository open(String indexes) {
		return new SailRepository(new LmdbStore(dir, new LmdbStoreConfig(indexes)));
	}
}
